/* Crypto known answers against the platform's Go implementation
 * (vectors_go.h is generated by its tests: npfcrypto vectors_test.go). */
#include <stdio.h>
#include <string.h>

#include "npf/cert.h"
#include "npf/crypto.h"
#include "npf/noise.h"
#include "vectors_go.h"

static int fails;

#define CHECK(cond, ...) do { \
    if (!(cond)) { fails++; fprintf(stderr, "FAIL %s:%d: ", __FILE__, __LINE__); \
                   fprintf(stderr, __VA_ARGS__); fprintf(stderr, "\n"); } \
} while (0)

static size_t unhex(const char *hex, uint8_t *out, size_t cap)
{
    size_t n = strlen(hex) / 2, i;
    if (n > cap)
        return 0;
    for (i = 0; i < n; i++) {
        unsigned v;
        sscanf(hex + 2 * i, "%2x", &v);
        out[i] = (uint8_t)v;
    }
    return n;
}

static int eqhex(const uint8_t *b, size_t n, const char *hex)
{
    uint8_t e[4096];
    size_t m = unhex(hex, e, sizeof e);
    return m == n && memcmp(b, e, n) == 0;
}

static void seed_of(uint8_t s[32], uint8_t base)
{
    int i;
    for (i = 0; i < 32; i++) s[i] = (uint8_t)(base + i);
}

static void test_identity(void)
{
    npf_identity id;
    uint8_t s[32], k[32], sig[64];
    seed_of(s, 0x01);
    npf_identity_from_seed(&id, s);
    CHECK(eqhex(id.sign_pub, 32, V_ID_SIGN_PUB), "identity sign_pub");
    CHECK(eqhex(id.dh_pub, 32, V_ID_DH_PUB), "identity dh_pub");
    CHECK(npf_fp(id.dh_pub) == V_ID_FP, "fp");
    npf_kdf2(k, "key", 3, "npf ws tunnel v1", 16, "a2b", 3);
    CHECK(eqhex(k, 32, V_KDF), "kdf");
    npf_sign2(sig, id.sign_sk, "npf-test", 8, "msg", 3);
    CHECK(eqhex(sig, 64, V_SIG), "ed25519 signature");
    CHECK(npf_verify2(sig, id.sign_pub, "npf-test", 8, "msg", 3) == 0, "verify");
    sig[0] ^= 1;
    CHECK(npf_verify2(sig, id.sign_pub, "npf-test", 8, "msg", 3) != 0, "verify tampered");
}

static void test_aead_rfc8439(void)
{
    /* RFC 8439 2.8.2 */
    uint8_t key[32], nonce[12], ad[12], out[200], back[200];
    const char *pt = "Ladies and Gentlemen of the class of '99: If I could offer you only one tip "
                     "for the future, sunscreen would be it.";
    size_t n = strlen(pt);
    int i;
    for (i = 0; i < 32; i++) key[i] = (uint8_t)(0x80 + i);
    unhex("070000004041424344454647", nonce, 12);
    unhex("50515253c0c1c2c3c4c5c6c7", ad, 12);
    npf_aead_seal(key, nonce, ad, 12, (const uint8_t *)pt, n, out);
    CHECK(eqhex(out + n, 16, "1ae10b594f09e26a7e902ecbd0600691"), "rfc8439 tag");
    CHECK(out[0] == 0xd3 && out[1] == 0x1a, "rfc8439 ciphertext");
    CHECK(npf_aead_open(key, nonce, ad, 12, out, n + 16, back) == 0 && memcmp(back, pt, n) == 0, "open");
    out[3] ^= 1;
    CHECK(npf_aead_open(key, nonce, ad, 12, out, n + 16, back) != 0, "open tampered");
}

static void test_b64(void)
{
    uint8_t in[5] = {0xfb, 0xff, 0x01, 0x02, 0x03}, out[8];
    char s[16];
    size_t n;
    n = npf_b64url_encode(in, 5, s);
    CHECK(n == 7 && strcmp(s, "-_8BAgM") == 0, "b64 encode %s", s);
    CHECK(npf_b64url_decode(s, n, out, sizeof out) == 5 && memcmp(out, in, 5) == 0, "b64 decode");
    CHECK(npf_b64url_decode("-_8BAgN", 7, out, sizeof out) < 0, "b64 non-canonical tail");
    CHECK(npf_b64url_decode("-_8B=", 5, out, sizeof out) < 0, "b64 padding");
    CHECK(npf_b64url_decode("-_8BAgM", 7, out, 4) < 0, "b64 capacity");
}

/* run a handshake between two local states, compare messages with Go */
static void noise_case(const char *name, int pattern, const uint8_t *pro, size_t plen, int pre_rs,
                       const uint8_t *psk, const char *const *msgs, int nmsg,
                       const char *k1hex, const char *k2hex, const char *hhex)
{
    npf_identity a, b;
    npf_noise_hs hi, hr;
    npf_noise_cs ti, ri, tr, rr;
    uint8_t s[32], m[512], p[64], k1[32], k2[32], h[64], kk1[32], kk2[32], hh[64];
    static const char *payload[] = {"one", "two", "three"};
    int i, n;
    seed_of(s, 0x01); npf_identity_from_seed(&a, s);
    seed_of(s, 0x41); npf_identity_from_seed(&b, s);
    CHECK(npf_noise_init(&hi, pattern, 1, pro, plen, a.dh_sk, pre_rs ? b.dh_pub : NULL, psk) == 0, "%s init", name);
    CHECK(npf_noise_init(&hr, pattern, 0, pro, plen, b.dh_sk, NULL, psk) == 0, "%s init r", name);
    seed_of(s, 0xa0); npf_noise_fix_ephemeral(&hi, s);
    seed_of(s, 0xc0); npf_noise_fix_ephemeral(&hr, s);
    for (i = 0; i < nmsg; i++) {
        npf_noise_hs *w = (i % 2) ? &hr : &hi, *r = (i % 2) ? &hi : &hr;
        n = npf_noise_write(w, (const uint8_t *)payload[i], strlen(payload[i]), m, sizeof m);
        CHECK(n > 0 && eqhex(m, (size_t)n, msgs[i]), "%s message %d", name, i + 1);
        n = npf_noise_read(r, m, (size_t)n, p, sizeof p);
        CHECK(n == (int)strlen(payload[i]) && memcmp(p, payload[i], (size_t)n) == 0, "%s read %d", name, i + 1);
    }
    CHECK(npf_noise_split(&hi, &ti, &ri, k1, k2, h) == 0, "%s split", name);
    CHECK(npf_noise_split(&hr, &tr, &rr, kk1, kk2, hh) == 0, "%s split r", name);
    CHECK(eqhex(k1, 32, k1hex) && eqhex(k2, 32, k2hex), "%s keys", name);
    CHECK(eqhex(h, 64, hhex) && memcmp(h, hh, 64) == 0, "%s hash", name);
    CHECK(memcmp(npf_noise_remote_static(&hr), a.dh_pub, 32) == 0, "%s responder learned initiator", name);
    CHECK(memcmp(ti.k, rr.k, 32) == 0 && memcmp(tr.k, ri.k, 32) == 0, "%s directions", name);
    if (pattern == NPF_NOISE_XK) {
        n = npf_noise_encrypt(&ti, NULL, 0, (const uint8_t *)"ping", 4, m);
        CHECK(n == 20 && eqhex(m, 20, V_XK_CT), "xk transport");
        CHECK(npf_noise_decrypt(&rr, NULL, 0, m, 20, p) == 4 && memcmp(p, "ping", 4) == 0, "xk transport decrypt");
        CHECK(npf_noise_decrypt(&rr, NULL, 0, m, 20, p) < 0, "xk replay rejected");
    }
}

static void test_noise(void)
{
    static const char *xk[] = {V_XK_M1, V_XK_M2, V_XK_M3};
    static const char *ik[] = {V_IK_M1, V_IK_M2};
    static const char *xx[] = {V_XX_M1, V_XX_M2, V_XX_M3};
    uint8_t pro[64], psk[32];
    size_t pl = unhex(V_IK_PROLOGUE, pro, sizeof pro);
    noise_case("xk", NPF_NOISE_XK, (const uint8_t *)"npf-ws-v1", 9, 1, NULL, xk, 3, V_XK_K1, V_XK_K2, V_XK_H);
    noise_case("ik", NPF_NOISE_IK, pro, pl, 1, NULL, ik, 2, V_IK_K1, V_IK_K2, V_IK_H);
    seed_of(psk, 0x70);
    noise_case("xxpsk3", NPF_NOISE_XXPSK3, (const uint8_t *)"npf-pair-v1", 11, 0, psk, xx, 3, V_XX_K1, V_XX_K2, V_XX_H);

    /* NNpsk0 (direct connections): no static keys */
    {
        npf_noise_hs hi, hr;
        uint8_t s[32], m[256], p[64], k1[32], k2[32], h[64];
        static const char *nn[] = {V_NN_M1, V_NN_M2};
        int i, n;
        seed_of(psk, 0x50);
        CHECK(npf_noise_init(&hi, NPF_NOISE_NNPSK0, 1, "npf-direct-v1", 13, NULL, NULL, psk) == 0, "nn init");
        CHECK(npf_noise_init(&hr, NPF_NOISE_NNPSK0, 0, "npf-direct-v1", 13, NULL, NULL, psk) == 0, "nn init r");
        seed_of(s, 0xa0); npf_noise_fix_ephemeral(&hi, s);
        seed_of(s, 0xc0); npf_noise_fix_ephemeral(&hr, s);
        for (i = 0; i < 2; i++) {
            static const char *pay[] = {"one", "two"};
            npf_noise_hs *w = i ? &hr : &hi, *r = i ? &hi : &hr;
            n = npf_noise_write(w, (const uint8_t *)pay[i], 3, m, sizeof m);
            CHECK(n > 0 && eqhex(m, (size_t)n, nn[i]), "nn message %d", i + 1);
            CHECK(npf_noise_read(r, m, (size_t)n, p, sizeof p) == 3, "nn read %d", i + 1);
        }
        CHECK(npf_noise_split(&hi, NULL, NULL, k1, k2, h) == 0 && eqhex(k1, 32, V_NN_K1) && eqhex(k2, 32, V_NN_K2)
              && eqhex(h, 64, V_NN_H), "nn keys");
        /* the wrong key cannot even produce a readable first message */
        seed_of(s, 0x51);
        npf_noise_init(&hi, NPF_NOISE_NNPSK0, 1, "npf-direct-v1", 13, NULL, NULL, s);
        npf_noise_init(&hr, NPF_NOISE_NNPSK0, 0, "npf-direct-v1", 13, NULL, NULL, psk);
        n = npf_noise_write(&hi, (const uint8_t *)"x", 1, m, sizeof m);
        CHECK(npf_noise_read(&hr, m, (size_t)n, p, sizeof p) < 0, "nn wrong psk rejected");
        seed_of(psk, 0x70);
    }

    /* wrong psk: the responder cannot read message 3 */
    {
        npf_identity a, b;
        npf_noise_hs hi, hr;
        uint8_t s[32], m[512], p[64], bad[32];
        int n;
        seed_of(s, 1); npf_identity_from_seed(&a, s);
        seed_of(s, 2); npf_identity_from_seed(&b, s);
        seed_of(bad, 0x71);
        npf_noise_init(&hi, NPF_NOISE_XXPSK3, 1, "x", 1, a.dh_sk, NULL, psk);
        npf_noise_init(&hr, NPF_NOISE_XXPSK3, 0, "x", 1, b.dh_sk, NULL, bad);
        n = npf_noise_write(&hi, NULL, 0, m, sizeof m); npf_noise_read(&hr, m, (size_t)n, p, sizeof p);
        n = npf_noise_write(&hr, NULL, 0, m, sizeof m); npf_noise_read(&hi, m, (size_t)n, p, sizeof p);
        n = npf_noise_write(&hi, NULL, 0, m, sizeof m);
        CHECK(npf_noise_read(&hr, m, (size_t)n, p, sizeof p) < 0, "wrong psk rejected");
    }
}

static void test_cert(void)
{
    uint8_t roots[1][32], inter_raw[512], leaf_raw[512], chain[1024], list[512];
    size_t il, ll, ln;
    npf_cert inter, leaf;
    const uint8_t *pl;
    size_t plen;
    unhex(V_ROOT_PUB, roots[0], 32);
    il = unhex(V_INTER_CERT, inter_raw, sizeof inter_raw);
    ll = unhex(V_LEAF_CERT, leaf_raw, sizeof leaf_raw);
    CHECK(npf_cert_parse(leaf_raw, ll, &leaf) == (int)ll, "parse leaf");
    CHECK(leaf.type == NPF_CERT_NODE && leaf.subject == 123456789 && leaf.key_gen == 1
          && leaf.vendor == 7 && leaf.product == 9, "leaf fields");
    memcpy(chain, inter_raw, il);
    memcpy(chain + il, leaf_raw, ll);
    CHECK(npf_cert_chain_parse(roots, 1, chain, il + ll, &inter, &leaf, 1800000000) == 0, "chain");
    CHECK(npf_cert_chain_parse(roots, 1, chain, il + ll, &inter, &leaf, 1950000000) != 0, "leaf expired");
    chain[il + 20] ^= 1;
    CHECK(npf_cert_chain_parse(roots, 1, chain, il + ll, &inter, &leaf, 1800000000) != 0, "tampered leaf");

    ln = unhex(V_SERVERLIST, list, sizeof list);
    CHECK(npf_serverlist_verify(roots, 1, list, ln, &pl, &plen) == 0
          && plen == 12 && memcmp(pl, "{\"serial\":5}", 12) == 0, "server list");
    list[ln - 1] ^= 1;
    CHECK(npf_serverlist_verify(roots, 1, list, ln, &pl, &plen) != 0, "server list tampered");
}

static void test_grant(void)
{
    uint8_t inter_raw[512], g[512], h[512], msg[64], exp[64], op[16], ch[16];
    npf_cert inter;
    npf_grant gr;
    size_t il = unhex(V_INTER_CERT, inter_raw, sizeof inter_raw), gl = unhex(V_GRANT, g, sizeof g);
    size_t hl = unhex(V_GRANT_HOSTED, h, sizeof h);
    npf_cert_parse(inter_raw, il, &inter);
    CHECK(npf_grant_verify(g, gl, inter.sign_pub, &gr) == 0 && gr.kind == NPF_GRANT_ACCOUNT && gr.account == 1001
          && gr.number == 123456789 && gr.expires == 1800000600, "account grant");
    CHECK(npf_grant_verify(h, hl, inter.sign_pub, &gr) == 0 && gr.kind == NPF_GRANT_HOSTED, "hosted grant");
    CHECK(npf_grant_target_allowed(&gr, "nas.local", 5000) && npf_grant_target_allowed(&gr, "127.0.0.1", 80)
          && !npf_grant_target_allowed(&gr, "127.0.0.1", 81), "hosted targets");
    g[20] ^= 1;
    CHECK(npf_grant_verify(g, gl, inter.sign_pub, &gr) != 0, "tampered grant");
    memset(op, 1, 16);
    memset(ch, 2, 16);
    CHECK(npf_bind_proof_msg(msg, 123456789, 1, 1001, op, ch, 1800000600) == 60 && eqhex(msg, 60, V_BIND_MSG),
          "bind proof message");
    (void)exp;
}

int test_crypto(void)
{
    test_identity();
    test_aead_rfc8439();
    test_b64();
    test_noise();
    test_cert();
    test_grant();
    return fails;
}
